#define MAXV 1000

typedef struct Edge { int to; struct Edge *next; } Edge;

/* returns number of vertices output; < V means a cycle exists */
int kahn(int V, Edge *adj[], int order[]) {
  int indeg[MAXV] = {0}, queue[MAXV], head = 0, tail = 0, out = 0;
  for (int u = 0; u < V; u++)
    for (Edge *e = adj[u]; e; e = e->next) indeg[e->to]++;
  for (int u = 0; u < V; u++)
    if (indeg[u] == 0) queue[tail++] = u;
  while (head < tail) {
    int u = queue[head++];
    order[out++] = u;
    for (Edge *e = adj[u]; e; e = e->next)
      if (--indeg[e->to] == 0) queue[tail++] = e->to;
  }
  return out;
}

/* state: 0 = unvisited, 1 = on current path, 2 = finished */
static int state[MAXV], pos;

/* returns 0 on success, 1 if a cycle is found */
int visit(int u, Edge *adj[], int order[], int V) {
  state[u] = 1;
  for (Edge *e = adj[u]; e; e = e->next) {
    if (state[e->to] == 1) return 1;                 /* back edge */
    if (state[e->to] == 0 && visit(e->to, adj, order, V)) return 1;
  }
  state[u] = 2;
  order[--pos] = u;                  /* fill from the back: finish order reversed */
  return 0;
}

int topo_dfs(int V, Edge *adj[], int order[]) {
  pos = V;
  for (int u = 0; u < V; u++) state[u] = 0;
  for (int u = 0; u < V; u++)
    if (state[u] == 0 && visit(u, adj, order, V)) return 0;
  return 1;
}

/* longest path ending at each vertex of a DAG, edges weighted */
for (int i = 0; i < V; i++) best[i] = 0;
for (int i = 0; i < V; i++) {
  int u = order[i];                      /* topological order */
  for (Edge *e = adj[u]; e; e = e->next)
    if (best[u] + e->w > best[e->to]) best[e->to] = best[u] + e->w;
}

/* returns 1 if order[] is a valid topological order of the graph */
int valid_order(int V, Edge *adj[], const int order[]) {
  int pos[V];
  for (int i = 0; i < V; i++) pos[i] = -1;
  for (int i = 0; i < V; i++) {
    if (order[i] < 0 || order[i] >= V || pos[order[i]] != -1) return 0;
    pos[order[i]] = i;
  }
  for (int u = 0; u < V; u++)
    for (Edge *e = adj[u]; e; e = e->next)
      if (pos[u] >= pos[e->to]) return 0;
  return 1;
}
